#include <emscripten.h>
EM_JS(void, capture, (), { console.log(new Error().stack); });
__attribute__((noinline)) int meaningful_lean_frame(int x) { capture(); return x+1; }
int main(void) { return meaningful_lean_frame(2)-3; }

structuredFrameProbe.formatter:
Error.prepareStackTrace = (_, frames) => JSON.stringify(frames.map(frame => {
  const result = {};
  for (const method of ['getFunctionName', 'getMethodName', 'getFileName', 'getScriptNameOrSourceURL', 'getLineNumber',
    'getColumnNumber', 'getPosition', 'getTypeName', 'isNative', 'toString']) {
    try { result[method] = typeof frame[method] === 'function' ? frame[method]() : 'unavailable'; }
    catch (error) { result[method] = { error: error.message }; }
  }
  try { result.function = frame.getFunction()?.name; } catch {}
  return result;
}), null, 2);
